### Async Data Loading

```kotlin
@Composable
override fun MainWindow(onClose: () -> Unit) {
    var data by remember { mutableStateOf<List<Item>>(emptyList()) }
    var loading by remember { mutableStateOf(true) }

    LaunchedEffect(Unit) {
        data = loadDataFromNetwork()
        loading = false
    }

    if (loading) {
        CircularProgressIndicator()
    } else {
        LazyColumn {
            items(data) { item ->
                ItemRow(item)
            }
        }
    }
}
