    val queuedMs = audioOutputManager.getQueuedDurationMs()

                    // 保存当前音频参数用于计算比特率
                    currentSampleRate = audioPacket.sampleRate
                    currentChannelCount = audioPacket.channelCount
                    currentAudioFormatValue = audioPacket.audioFormat

                    // 计算原始频谱 (Raw Spectrum)
