                            break
                        }
                    }
                }
            }
            zipFile.delete()
            if (svvFile.exists()) svvFile else null
        } catch (e: Exception) {
            Logger.e("VBCableManager", "Failed to download/extract SoundVolumeView: ${e.message}", e)
            if (zipFile.exists()) zipFile.delete()
            null
        }
    }

