        }
    }

    suspend fun sendPluginSync(plugins: List<PluginInfoMessage>, platform: String) {
        try {
            sendChannel?.send(MessageWrapper(pluginSync = PluginSyncMessage(plugins, platform)))
        } catch (e: Exception) {
