package com.lanrhyme.micyou.network

import com.lanrhyme.micyou.*
import kotlinx.coroutines.*
import kotlinx.serialization.ExperimentalSerializationApi
import kotlinx.serialization.decodeFromByteArray
import kotlinx.serialization.protobuf.ProtoBuf
import java.net.DatagramPacket
import java.net.DatagramSocket
import java.net.InetSocketAddress

/**
 * Handles UDP audio data connection (Desktop server).
 * Responsibilities include:
 * 1. Receiving UDP audio packets
 * 2. Parsing and validating packet format
 * 3. Detecting packet loss/reordering using sequence numbers
 * 4. Dispatching audio packets to listeners
 * 
 * Unlike ConnectionHandler, the UDP processor:
 * - Does not require handshake (UDP is connectionless)
 * - Does not send control messages (control messages go through TCP channel)
 * - Tolerates packet loss (audio can handle small amounts of loss)
 */
class UdpConnectionHandler(
    private val port: Int,
    private val onAudioPacketReceived: suspend (AudioPacketMessage) -> Unit,
    private val onError: (String) -> Unit,
    private val onAudioPacketOrderedReceived: ((AudioPacketMessageOrdered) -> Unit)? = null
) {
    @OptIn(ExperimentalSerializationApi::class)
    private val proto = ProtoBuf { }

    private var udpSocket: DatagramSocket? = null
    private var handlerJob: Job? = null
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    // Client address mapping (currently supports single client only)
    @Volatile
    private var clientAddress: InetSocketAddress? = null

    // Sequence number tracking (for packet loss statistics)
    @Volatile
    private var expectedSequenceNumber = 0
    @Volatile
    private var packetsReceived = 0L
    @Volatile
    private var packetsLost = 0L

    // Jitter calculation
    @Volatile
    private var lastTransmitTime = 0L
    @Volatile
    private var lastReceiveTime = 0L
    @Volatile
    private var jitter = 0.0

    private var lastLossLogTime = 0L
    private var suppressedLossLogs = 0
    private var lastOutOfOrderLogTime = 0L

// Jitter calculation
    @Volatile
    private var lastTransmitTime = 0L
    @Volatile
    private var lastReceiveTime = 0L
    @Volatile
    private var jitter = 0.0

    private var lastLossLogTime = 0L
    private var suppressedLossLogs = 0
    private var lastOutOfOrderLogTime = 0L
    private var suppressedOutOfOrderLogs = 0
    /**
     * Starts the UDP receiving loop.
     * This function is non-blocking and runs in a background coroutine.
     */
    fun start() {
        handlerJob?.takeIf { it.isActive }?.let {
            Logger.w("UdpConnectionHandler", "UDP handler is already running")
            return
        }

        handlerJob = scope.launch {
            runUdpReceiver()
        }
    }

    /**
     * Stops the UDP receiver.
     */
    suspend fun stop() {
        handlerJob?.cancel()
        withTimeoutOrNull(2000) {
            handlerJob?.join()
        }
        cleanup()
    }

    /**
     * Gets statistics (for debugging/monitoring)
     */
    fun getStats(): UdpStats = UdpStats(
        packetsReceived = packetsReceived,
        packetsLost = packetsLost,
        jitter = jitter,
        clientAddress = clientAddress
    )

    private suspend fun runUdpReceiver() {
        try {
            udpSocket = DatagramSocket(null).also { socket ->
                socket.reuseAddress = true
                socket.bind(java.net.InetSocketAddress(port))
                // Set receive buffer size for audio stream
                socket.receiveBufferSize = 2 * 1024 * 1024 // 2MB
                val actualBufferSize = socket.receiveBufferSize
                Logger.i("UdpConnectionHandler", "UDP receiver started on port $port, receive buffer: ${actualBufferSize / 1024}KB (requested: 2048KB)")
                if (actualBufferSize < 512 * 1024) {
                    Logger.w("UdpConnectionHandler", "UDP receive buffer is smaller than expected (${actualBufferSize / 1024}KB). Consider adjusting OS UDP buffer limits.")

private suspend fun runUdpReceiver() {
        try {
            udpSocket = DatagramSocket(null).also { socket ->
                socket.reuseAddress = true
                socket.bind(java.net.InetSocketAddress(port))
                // Set receive buffer size for audio stream
                socket.receiveBufferSize = 2 * 1024 * 1024 // 2MB
                val actualBufferSize = socket.receiveBufferSize
                Logger.i("UdpConnectionHandler", "UDP receiver started on port $port, receive buffer: ${actualBufferSize / 1024}KB (requested: 2048KB)")
                if (actualBufferSize < 512 * 1024) {
                    Logger.w("UdpConnectionHandler", "UDP receive buffer is smaller than expected (${actualBufferSize / 1024}KB). Consider adjusting OS UDP buffer limits.")
                }
            }
    val buffer = ByteArray(Constants.MAX_PACKET_SIZE)

            while (currentCoroutineContext().isActive) {
                val packet = DatagramPacket(buffer, buffer.size)
                try {
                    udpSocket?.receive(packet)
                } catch (e: java.net.SocketException) {
                    // This exception is thrown when the socket is closed, exit normally
                    if (currentCoroutineContext().isActive) {
                        Logger.e("UdpConnectionHandler", "UDP receive error", e)
                    }
                    break
                }
    val senderAddress = InetSocketAddress(packet.address, packet.port)

                // Record the first client address
                if (clientAddress == null) {
                    clientAddress = senderAddress
                    Logger.i("UdpConnectionHandler", "UDP client connected: ${senderAddress.address.hostAddress}:${senderAddress.port}")
                }

                processUdpPacket(packet.data, packet.offset, packet.length)
            }
        } catch (e: Exception) {
            if (currentCoroutineContext().isActive) {
                Logger.e("UdpConnectionHandler", "UDP receiver fatal error", e)
                onError("UDP receiver error: ${e.message}")
            }
        } finally {
            cleanup()
        }
    }

    @OptIn(ExperimentalSerializationApi::class)
    private suspend fun processUdpPacket(data: ByteArray, offset: Int, length: Int) {
        if (length < 8) {
            // Packet too small, skip
            return
        }

        // Parse magic number (4-byte big-endian)
        val magic = ((data[offset].toInt() and 0xFF) shl 24) or
                    ((data[offset + 1].toInt() and 0xFF) shl 16) or
                    ((data[offset + 2].toInt() and 0xFF) shl 8) or
                    (data[offset + 3].toInt() and 0xFF)

private suspend fun processUdpPacket(data: ByteArray, offset: Int, length: Int) {
        if (length < 8) {
            // Packet too small, skip
            return
        }

        // Parse magic number (4-byte big-endian)
        val magic = ((data[offset].toInt() and 0xFF) shl 24) or
                    ((data[offset + 1].toInt() and 0xFF) shl 16) or
                    ((data[offset + 2].toInt() and 0xFF) shl 8) or
                    (data[offset + 3].toInt() and 0xFF)

        if (magic != UDP_PACKET_MAGIC) {
            Logger.w("UdpConnectionHandler", "UDP packet magic mismatch: 0x${magic.toString(16).uppercase()}")
            return
        }

        // Parse length (4-byte big-endian)
        val payloadLength = ((data[offset + 4].toInt() and 0xFF) shl 24) or
                     ((data[offset + 5].toInt() and 0xFF) shl 16) or
                     ((data[offset + 6].toInt() and 0xFF) shl 8) or
                     (data[offset + 7].toInt() and 0xFF)

        if (payloadLength <= 0 || payloadLength > length - 8) {
            Logger.w("UdpConnectionHandler", "UDP packet length invalid: $payloadLength")
            return
        }
    val payloadStart = offset + 8

        try {
            val wrapper: MessageWrapper = proto.decodeFromByteArray(MessageWrapper.serializer(), data.copyOfRange(payloadStart, payloadStart + payloadLength))

            // UDP channel only processes audio packets
            val audioPacket = wrapper.audioPacket?.audioPacket
            if (audioPacket != null) {
                // Sequence number tracking
                val seqNum = wrapper.audioPacket.sequenceNumber
                if (packetsReceived == 0L) {
                    expectedSequenceNumber = seqNum
                    packetsReceived++
                } else {
                    val expected = expectedSequenceNumber + 1
                    if (seqNum != expected) {
                        // Use unsigned comparison for sequence number (handles Int wrap correctly)
                        val diffUnsigned = (seqNum.toUInt() - expected.toUInt()).toLong() and 0xFFFFFFFFL
                        // If diff < 0x80000000u, seqNum is "after" expected (normal loss)
                        // If diff >= 0x80000000u, seqNum is "before" expected (out-of-order/repeat)
                        val isGapForward = diffUnsigned < 0x80000000L
                        if (isGapForward) {
                            // Normal packet loss: received sequence number > expected
                            val lost = diffUnsigned
                            // Sanity check: limit max loss per gap to prevent absurd counts
                            val cappedLost = minOf(lost, 1000L)
                            packetsLost += cappedLost
                            expectedSequenceNumber = seqNum
                            packetsReceived++
                            val now = System.currentTimeMillis()
                            if (now - lastLossLogTime > 1000) {
                                Logger.d("UdpConnectionHandler", "UDP loss detected: expected $expected, received $seqNum, lost $cappedLost packets. (Suppressed $suppressedLossLogs similar logs)")
                                lastLossLogTime = now

if (isGapForward) {
                            // Normal packet loss: received sequence number > expected
                            val lost = diffUnsigned
                            // Sanity check: limit max loss per gap to prevent absurd counts
                            val cappedLost = minOf(lost, 1000L)
                            packetsLost += cappedLost
                            expectedSequenceNumber = seqNum
                            packetsReceived++
                            val now = System.currentTimeMillis()
                            if (now - lastLossLogTime > 1000) {
                                Logger.d("UdpConnectionHandler", "UDP loss detected: expected $expected, received $seqNum, lost $cappedLost packets. (Suppressed $suppressedLossLogs similar logs)")
                                lastLossLogTime = now
                                suppressedLossLogs = 0
                            } else {
                                suppressedLossLogs++
                            }
                        } else {
                            // Out-of-order or duplicate packet: do NOT advance expectedSequenceNumber
                            // This prevents cascading false loss detection when UDP delivers packets out of order
                            packetsReceived++
                            val now = System.currentTimeMillis()
                            if (now - lastOutOfOrderLogTime > 1000) {
                                Logger.d("UdpConnectionHandler", "UDP out-of-order packet: expected $expected, received $seqNum (ignored for loss tracking). (Suppressed $suppressedOutOfOrderLogs similar logs)")
                                lastOutOfOrderLogTime = now
                                suppressedOutOfOrderLogs = 0
                            } else {
                                suppressedOutOfOrderLogs++
                            }
                        }
                    } else {
                        expectedSequenceNumber = seqNum
                        packetsReceived++
                    }
                }

                // Jitter calculation (RFC 3550 variant)
                val transmitTime = wrapper.audioPacket.timestamp
                val receiveTime = System.currentTimeMillis()
                if (packetsReceived > 1 && transmitTime > 0 && lastTransmitTime > 0) {
                    val d = (receiveTime - lastReceiveTime) - (transmitTime - lastTransmitTime)
                    jitter += (kotlin.math.abs(d) - jitter) / 16.0
                }
                lastTransmitTime = transmitTime
                lastReceiveTime = receiveTime

                // 如果有有序包回调，使用它；否则直接调用音频包回调
                if (onAudioPacketOrderedReceived != null) {
                    onAudioPacketOrderedReceived.invoke(wrapper.audioPacket)
                } else {
                    onAudioPacketReceived(audioPacket)
                }
            }
        } catch (e: Exception) {
            Logger.e("UdpConnectionHandler", "UDP packet decoding failed", e)
        }
    }

    private fun cleanup() {
        try {
            udpSocket?.close()

} else {
                    onAudioPacketReceived(audioPacket)
                }
            }
        } catch (e: Exception) {
            Logger.e("UdpConnectionHandler", "UDP packet decoding failed", e)
        }
    }

    private fun cleanup() {
        try {
            udpSocket?.close()
        } catch (e: Exception) {
            Logger.w("UdpConnectionHandler", "Error closing UDP socket: ${e.message}")
        }
        udpSocket = null
        clientAddress = null
    }

    data class UdpStats(
        val packetsReceived: Long,
        val packetsLost: Long,
        val jitter: Double,
        val clientAddress: InetSocketAddress?
    ) {
        val lossRate: Double
            get() = if (packetsReceived + packetsLost > 0) {
                packetsLost.toDouble() / (packetsReceived + packetsLost) * 100.0
            } else 0.0
    }
}

package com.lanrhyme.micyou.network

import com.lanrhyme.micyou.Logger
import java.io.IOException

object WebHtmlPage {
    private const val HTML_RESOURCE = "web_client.html"
    private const val JS_RESOURCE = "alpine.min.js"

    private val cachedHtml: String by lazy {
        val stream = this.javaClass.classLoader.getResourceAsStream(HTML_RESOURCE)
            ?: throw IOException("Resource not found: $HTML_RESOURCE")
        stream.bufferedReader(Charsets.UTF_8).use {
            it.readText()
                .also { text ->
                    Logger.i("WebHtmlPage", "HTML page loaded from resource, length=${text.length}")
                }
        }
    }

    private val cachedJs: ByteArray by lazy {
        val stream = this.javaClass.classLoader.getResourceAsStream(JS_RESOURCE)
            ?: throw IOException("Resource not found: $JS_RESOURCE")
        stream.use {
            it.readBytes()
                .also { bytes ->
                    Logger.i("WebHtmlPage", "JS file loaded from resource, length=${bytes.size}")
                }
        }
    }

    fun getHtml(): String = cachedHtml
    fun getJs(): ByteArray = cachedJs
}

private val _clientCountFlow = MutableStateFlow(0)
    val clientCountFlow: StateFlow<Int> = _clientCountFlow.asStateFlow()

    @Volatile
    var isRunning: Boolean = false
        private set

    private val htmlContent: String by lazy { WebHtmlPage.getHtml() }

    fun start(port: Int = this.port) {
        if (isRunning) {
            Logger.w("WebServer", "WebServer is already running")
            return
        }

        _state.value = StreamState.Connecting

        try {
            val keyStore = SelfSignedCertificate.generate()
            val password = SelfSignedCertificate.getKeyStorePassword()
            server = embeddedServer(Netty,
                environment = applicationEnvironment {},
                configure = {
                    sslConnector(
                        keyStore = keyStore,
                        keyAlias = SelfSignedCertificate.getCertAlias(),
                        keyStorePassword = { password.toCharArray() },
                        privateKeyPassword = { password.toCharArray() }
                    ) {
                        this.port = port
                        host = "0.0.0.0"
                    }
                }
            ) {
                install(WebSockets) {
                    pingPeriod = 30.seconds
                    timeout = 15.seconds
                }
                install(CORS) {
                    allowHost("localhost")
                    allowHost("127.0.0.1")
                    for (ip in SelfSignedCertificate.getLanIpAddresses()) {
                        allowHost(ip)
                    }
                }
                routing {
                    get("/") {
                        call.respondText(htmlContent, ContentType.Text.Html)
                    }
                    get("/alpine.min.js") {
                        call.respondBytes(WebHtmlPage.getJs(), ContentType.Application.JavaScript)
                    }
                    webSocket("/ws") {
                        val origin = call.request.headers["Origin"]
                        if (!isValidWebSocketOrigin(origin)) {
                            Logger.w("WebServer", "Rejected WebSocket from untrusted origin: $origin")
                            try {
                                send(Frame.Close(CloseReason(CloseReason.Codes.VIOLATED_POLICY, "Invalid origin")))
                            } catch (_: Exception) {}
                            return@webSocket

}
                    get("/alpine.min.js") {
                        call.respondBytes(WebHtmlPage.getJs(), ContentType.Application.JavaScript)
                    }
                    webSocket("/ws") {
                        val origin = call.request.headers["Origin"]
                        if (!isValidWebSocketOrigin(origin)) {
                            Logger.w("WebServer", "Rejected WebSocket from untrusted origin: $origin")
                            try {
                                send(Frame.Close(CloseReason(CloseReason.Codes.VIOLATED_POLICY, "Invalid origin")))
                            } catch (_: Exception) {}
                            return@webSocket
                        }
                        handleWebSocketSession()
                    }
                }
            }

            server!!.start(wait = false)

            isRunning = true
            _state.value = StreamState.Connecting
            Logger.i("WebServer", "HTTPS+WebSocket server started on port $port")
        } catch (e: Exception) {
            _state.value = StreamState.Error
            _lastError.value = "Failed to start web server: ${e.message}"
            Logger.e("WebServer", "Failed to start web server", e)
        }
    }

    private suspend fun DefaultWebSocketServerSession.handleWebSocketSession() {
        val currentCount = clientCount.incrementAndGet()
        _clientCountFlow.value = currentCount
        if (currentCount == 1) {
            _state.value = StreamState.Streaming
        }
        Logger.i("WebServer", "WebSocket client connected (total: $currentCount)")

        try {
            for (frame in incoming) {
                if (!isActive) break
                when (frame) {
                    is Frame.Binary -> {
                        processAudioData(frame.data)
                    }
                    is Frame.Ping -> {
                        send(Frame.Pong(frame.data))
                    }
                    is Frame.Close -> {
                        break
                    }
                    else -> {}
                }
            }
        } catch (e: Exception) {
            // WebSocket session errors (client disconnect, etc.) are normal - don't log as warning
        } finally {
            val remaining = clientCount.decrementAndGet()
            _clientCountFlow.value = remaining
            if (remaining == 0) _state.value = StreamState.Idle

is Frame.Close -> {
                        break
                    }
                    else -> {}
                }
            }
        } catch (e: Exception) {
            // WebSocket session errors (client disconnect, etc.) are normal - don't log as warning
        } finally {
            val remaining = clientCount.decrementAndGet()
            _clientCountFlow.value = remaining
            if (remaining == 0) _state.value = StreamState.Idle
            Logger.i("WebServer", "WebSocket client disconnected (remaining: $remaining)")
        }
    }

    private fun isValidWebSocketOrigin(origin: String?): Boolean {
        if (origin.isNullOrBlank()) return true
        val host = try {
            java.net.URI(origin).host
        } catch (e: Exception) {
            Logger.w("WebServer", "Invalid Origin URL: $origin")
            return false
        }
        if (host == "localhost" || host == "127.0.0.1") return true
        val lanIps = SelfSignedCertificate.getLanIpAddresses()
        if (host in lanIps) return true
        return false
    }

    fun stop() {
        isRunning = false
        _state.value = StreamState.Idle
        try {
            server?.stop(1000, 2000)
        } catch (_: Exception) {}
        server = null
        clientCount.set(0)
        _clientCountFlow.value = 0
        Logger.i("WebServer", "WebServer stopped")
    }

    private fun processAudioData(float32Bytes: ByteArray) {
        try {
            if (float32Bytes.size > Constants.MAX_PACKET_SIZE) {
                Logger.w("WebServer", "Rejected oversized audio frame: ${float32Bytes.size} bytes (max ${Constants.MAX_PACKET_SIZE})")
                return
            }
            val numFloats = float32Bytes.size / 4
            if (numFloats == 0) return
            val pcmBytes = ByteArray(numFloats * 2)
            val inBuf = ByteBuffer.wrap(float32Bytes).order(ByteOrder.LITTLE_ENDIAN)
            var outIdx = 0
            for (i in 0 until numFloats) {
                if (inBuf.remaining() < 4) break
                val shortVal = (inBuf.float * 32767f).coerceIn(-32767f, 32767f).toInt()
                pcmBytes[outIdx] = shortVal.toByte()
                pcmBytes[outIdx + 1] = (shortVal shr 8).toByte()
                outIdx += 2
            }

val numFloats = float32Bytes.size / 4
            if (numFloats == 0) return
            val pcmBytes = ByteArray(numFloats * 2)
            val inBuf = ByteBuffer.wrap(float32Bytes).order(ByteOrder.LITTLE_ENDIAN)
            var outIdx = 0
            for (i in 0 until numFloats) {
                if (inBuf.remaining() < 4) break
                val shortVal = (inBuf.float * 32767f).coerceIn(-32767f, 32767f).toInt()
                pcmBytes[outIdx] = shortVal.toByte()
                pcmBytes[outIdx + 1] = (shortVal shr 8).toByte()
                outIdx += 2
            }
            if (outIdx == 0) return
            val slicedPcm = if (outIdx == pcmBytes.size) pcmBytes else pcmBytes.copyOf(outIdx)
            val audioPacket = AudioPacketMessage(buffer = slicedPcm, sampleRate = 48000, channelCount = 1, audioFormat = 2)
            onAudioPacketReceived(audioPacket)
        } catch (e: Exception) {
            Logger.w("WebServer", "Error processing audio data: ${e.message}")
        }
    }

    fun getClientCount(): Int = clientCount.get()
}

package com.lanrhyme.micyou.audio

import kotlin.math.sqrt

/**
 * 自动增益控制 (AGC) 效果器
 * 自动调整音频音量以保持一致的输出水平
 *
 * AGC 平滑系数说明：
 * - DECAY_RATE (0.005): 快速降低增益，防止声音突然增大造成刺耳
 * - ATTACK_RATE (0.01): 缓慢增加增益，平滑提升避免突变
 * - SILENT_RECOVERY_RATE (0.001): 静音时缓慢恢复到默认增益
 */
class AGCEffect : AudioEffect {

    companion object {
        // AGC 平滑系数常量
        /** 快速衰减率：当需要降低增益时使用，防止声音突增 */
        private const val AGC_DECAY_RATE = 0.005f
        /** 慢速增长率：当需要提升增益时使用，平滑提升 */
        private const val AGC_ATTACK_RATE = 0.01f
        /** 静音恢复率：静音时缓慢恢复到默认增益 1.0 */
        private const val AGC_SILENT_RECOVERY_RATE = 0.001f

        // 增益范围限制
        /** 最小增益倍数，防止过度衰减 */
        private const val MIN_GAIN_LIMIT = 0.5f
        /** 最大增益倍数，防止过度放大产生削波失真 */
        private const val MAX_GAIN_LIMIT = 3.0f
        /** 最终输出的最小增益 */
        private const val MIN_OUTPUT_GAIN = 0.8f
        /** 最终输出的最大增益，限制在安全范围内 */
        private const val MAX_OUTPUT_GAIN = 3.0f

        // RMS 相关常量
        /** RMS 最小阈值，低于此值视为静音 */
        private const val RMS_MIN_THRESHOLD = 0.001f
        /** 目标 RMS 最小值（标准化后） */
        private const val TARGET_RMS_MIN = 0.01f
        /** 目标 RMS 最大值（标准化后） */
        private const val TARGET_RMS_MAX = 0.9f
        /** 增益计算时的微小偏移，防止除零 */
        private const val EPSILON = 1e-6f
        /** 初始增益包络值 */
        private const val INITIAL_ENVELOPE = 1.0f

        // 数值常量
        /** Short 值范围的最大值 */
        private const val SHORT_MAX_VALUE = 32768.0f
        /** 静音恢复时的目标增益 */
        private const val SILENT_TARGET_GAIN = 1.0f
    }

    // 是否启用 AGC
    var enableAGC: Boolean = false
    // 目标音量水平 (RMS)
    var agcTargetLevel: Int = 32000

    // 平滑系数
    var attackRate: Float = AGC_ATTACK_RATE

private const val SHORT_MAX_VALUE = 32768.0f
        /** 静音恢复时的目标增益 */
        private const val SILENT_TARGET_GAIN = 1.0f
    }

    // 是否启用 AGC
    var enableAGC: Boolean = false
    // 目标音量水平 (RMS)
    var agcTargetLevel: Int = 32000

    // 平滑系数
    var attackRate: Float = AGC_ATTACK_RATE
    var decayRate: Float = AGC_DECAY_RATE

    private var agcEnvelope: Float = 0f

    override fun process(input: ShortArray, channelCount: Int): ShortArray {
        if (!enableAGC || agcTargetLevel <= 0) return input

        // 计算当前帧的 RMS
        var sumSquares = 0.0
        for (s in input) {
            val sample = s.toDouble() / SHORT_MAX_VALUE
            sumSquares += sample * sample
        }
    val rms = sqrt(sumSquares / input.size.toDouble())

        // 目标 RMS (标准化到 0.0-1.0)
    val targetRms = (agcTargetLevel.toDouble() / SHORT_MAX_VALUE.toDouble()).coerceIn(TARGET_RMS_MIN.toDouble(), TARGET_RMS_MAX.toDouble())

        if (rms > RMS_MIN_THRESHOLD) {
            val error = targetRms / (rms + EPSILON)
    val desiredGain = error.toFloat().coerceIn(MIN_GAIN_LIMIT, MAX_GAIN_LIMIT)

            if (agcEnvelope == 0f) {
                agcEnvelope = INITIAL_ENVELOPE
            }

            // 平滑增益变化：降低快、增加慢
            val smoothing = if (desiredGain < agcEnvelope) {
                decayRate  // 使用可配置的衰减率
            } else {
                attackRate  // 使用可配置的增长率
            }
            agcEnvelope = agcEnvelope * (1f - smoothing) + desiredGain * smoothing
        } else {
            // 静音时缓慢恢复到默认增益
            agcEnvelope = agcEnvelope * (1f - AGC_SILENT_RECOVERY_RATE) + SILENT_TARGET_GAIN * AGC_SILENT_RECOVERY_RATE
        }
    val finalGain = agcEnvelope.coerceIn(MIN_OUTPUT_GAIN, MAX_OUTPUT_GAIN)

        // 应用增益
        for (i in input.indices) {
            val v = (input[i].toInt() * finalGain).toInt().coerceIn(-32768, 32767)
            input[i] = v.toShort()
        }
        return input
    }

    override fun reset() {

}
    val finalGain = agcEnvelope.coerceIn(MIN_OUTPUT_GAIN, MAX_OUTPUT_GAIN)

        // 应用增益
        for (i in input.indices) {
            val v = (input[i].toInt() * finalGain).toInt().coerceIn(-32768, 32767)
            input[i] = v.toShort()
        }
        return input
    }

    override fun reset() {
        agcEnvelope = 0f
    }

    override fun release() {
        reset()
    }
}

