        // JTransforms realForward 输出格式：
        // fftBuffer[0] = DC (实数)
        // fftBuffer[1] = Nyquist (实数，当 n 为偶数时)
        // fftBuffer[2*i] = 实部, fftBuffer[2*i+1] = 虚部 (i=1..n/2-1)
    val specSize = frameSize / 2 + 1

        // 转换为 [batch, freq_bins, 1, 2] 格式 (实部, 虚部)
