private fun parseLanguageCode(code: String): Pair<String, String> {
    return when (code) {
        "zh-TW" -> "zh" to "TW"
        "zh-HK" -> "zh" to "HK"
        "zh-rSS" -> "zh" to "SS"
        "system" -> "" to ""
        else -> code to ""
    }
}

