/**
 * 音频指标数据
 * 用于监控比特率、延迟、丢包和抖动
 */
data class AudioMetrics(
    /** 比特率 (bps) = sampleRate * channels * bitsPerSample */
    val bitrate: Int,
    /** 采样率 (Hz) */
    val sampleRate: Int = 0,
    /** 总延迟估算（毫秒） */
    val latencyMs: Long,
    /** 网络延迟 (RTT，毫秒) */
    val networkLatencyMs: Long = 0,
    /** 丢包率 (0.0 - 100.0) */
    val packetLossRate: Double = 0.0,
    /** 抖动 (毫秒) */
    val jitterMs: Double = 0.0,
    /** 缓冲区时长 (毫秒) */
    val bufferDurationMs: Long = 0
) {
    /** 获取 kbps 格式的比特率 */
    fun bitrateKbps(): Int = bitrate / 1000

    /** 获取 Mbps 格式的比特率 */
    fun bitrateMbps(): Float = bitrate / 1_000_000f

    companion object {
        /**
         * 计算比特率
         * @param sampleRate 采样率
         * @param channels 通道数
         * @param bitsPerSample 每样本位数
         */
        fun calculateBitrate(sampleRate: Int, channels: Int, bitsPerSample: Int): Int {
            return sampleRate * channels * bitsPerSample
        }
    }
}

