/**
 * 格式化 dB 值显示
 */
private fun formatDb(db: Float): String {
    return if (db <= AudioLevelData.NEGATIVE_INFINITY_DB) {
        "-∞ dB"
    } else {
        "${db.toInt()} dB"
    }
}

