@Composable
fun SaturationValuePanel(
    hue: Float,
    saturation: Float,
    value: Float,
    onSaturationValueChanged: (Float, Float) -> Unit,
    modifier: Modifier = Modifier
) {
    Box(modifier = modifier.clip(RoundedCornerShape(8.dp))) {
        Canvas(
            modifier = Modifier
                .fillMaxSize()
                .pointerInput(Unit) {
                    detectDragGestures { change, _ ->
                        val sat = (change.position.x / size.width).coerceIn(0f, 1f)
    val v = (1f - change.position.y / size.height).coerceIn(0f, 1f)
                        onSaturationValueChanged(sat, v)
                    }
                }
                .pointerInput(Unit) {
                    detectTapGestures { offset ->
                        val sat = (offset.x / size.width).coerceIn(0f, 1f)
    val v = (1f - offset.y / size.height).coerceIn(0f, 1f)
                        onSaturationValueChanged(sat, v)
                    }
                }
        ) {
            val width = size.width
            val height = size.height

            // 绘制基础色相渐变（从左到右：白色 -> 纯色）
            // 使用最大明度(V=1)来绘制，这样面板背景不会随选择改变
            for (x in 0..width.toInt() step 2) {
                val sat = x / width
                val color = Color.hsv(hue, sat, 1f) // 始终使用 V=1
                drawLine(
                    color = color,
                    start = Offset(x.toFloat(), 0f),
                    end = Offset(x.toFloat(), height),
                    strokeWidth = 2f
                )
            }

            // 绘制明度渐变遮罩（从上到下：透明 -> 黑色）
            // 这样无论选择什么颜色，面板左上角始终是白色
            drawRect(
                brush = Brush.verticalGradient(
                    colors = listOf(
                        Color.Transparent,  // 顶部保持原色（白色到纯色）
                        Color.Black          // 底部变为黑色
                    ),
                    startY = 0f,
                    endY = height
                )
            )

            // 绘制选择指示器
            val indicatorX = saturation * width

brush = Brush.verticalGradient(
                    colors = listOf(
                        Color.Transparent,  // 顶部保持原色（白色到纯色）
                        Color.Black          // 底部变为黑色
                    ),
                    startY = 0f,
                    endY = height
                )
            )

            // 绘制选择指示器
            val indicatorX = saturation * width
            val indicatorY = (1f - value) * height

            drawCircle(
                color = Color.White,
                radius = 8f,
                center = Offset(indicatorX, indicatorY),
                style = Stroke(width = 3f)
            )
            drawCircle(
                color = Color.Black,
                radius = 8f,
                center = Offset(indicatorX, indicatorY),
                style = Stroke(width = 1f)
            )
        }
    }
}

