                visible = showSettings,
                enter = slideInHorizontally(
                    initialOffsetX = { it },
                    animationSpec = tween(360, easing = EasingFunctions.EaseOutExpo)
                ) + fadeIn(animationSpec = tween(240)),
                exit = slideOutHorizontally(
