                    animationSpec = tween(300, easing = EasingFunctions.EaseInOutExpo)
                ) + fadeOut(animationSpec = tween(200))
            ) {
                Surface(modifier = Modifier.fillMaxSize()) {
                    DesktopSettings(viewModel = viewModel, onClose = { showSettings = false })
                }
            }
        }
    }
