    @ProtoNumber(3)
    val mute: MuteMessage? = null,
    @ProtoNumber(4)
    val pluginSync: PluginSyncMessage? = null,
    @ProtoNumber(5)
    val ping: PingMessage? = null,
    @ProtoNumber(6)
    val pong: PongMessage? = null
)

