            if (value.isBlank()) {
                prefs.edit().putString(key, value).apply()
                return
            }
    val encrypted = encryptMirrorCdk(value)
            if (encrypted != null) {
                prefs.edit().putString(key, encrypted).apply()
            }
            return
        }

        prefs.edit().putString(key, value).apply()
    }

