    val parts2 = version2.split(".")
    val maxLength = maxOf(parts1.size, parts2.size)

        for (i in 0 until maxLength) {
            val v1 = parts1.getOrNull(i)?.toIntOrNull() ?: 0
            val v2 = parts2.getOrNull(i)?.toIntOrNull() ?: 0

            if (v1 != v2) {
                return v1 - v2
            }
        }

