    Write-Host "[错误] 未找到 Java 运行时环境。" -ForegroundColor Red
    Write-Host ""
    Write-Host "请安装 Java 17 或更高版本，并确保以下之一：" -ForegroundColor Yellow
    Write-Host "  1. JAVA_HOME 环境变量已设置"
